F="C:/Users/dasbl/.claude/projects/D--the-synaptic-sea-2d/a5c30614-4e6e-4b6b-a781-54ec94879f80/tool-results/bdzhwvqfv.txt"; cat > $TEMP/wd.js <<'EOF'
const fs=require('fs');const L=fs.readFileSync(process.argv[2],'utf8').split('\n');
let minus=[],plus=[];
function flush(){const n=Math.min(minus.length,plus.length);
for(let i=0;i<n;i++){const a=minus[i].split(/(\s+)/),b=plus[i].split(/(\s+)/);
let s=0;while(s<a.length&&s<b.length&&a[s]===b[s])s++;let e=0;while(e<a.length-s&&e<b.length-s&&a[a.length-1-e]===b[b.length-1-e])e++;
console.log('--- '+minus[i].slice(0,60));console.log('OLD: '+a.slice(Math.max(0,s-6),a.length-e+6).join(''));console.log('NEW: '+b.slice(Math.max(0,s-6),b.length-e+6).join(''));console.log();}
minus=[];plus=[];}
for(const l of L){if(l.startsWith('---')||l.startsWith('+++'))continue;if(l.startsWith('-'))minus.push(l.slice(1));else if(l.startsWith('+'))plus.push(l.slice(1));else flush();}
flush();
EOF
node $TEMP/wd.js "$F"

